cy.visit('/cette-page-nexiste-vraiment-pas-42', {
  failOnStatusCode: false
});
// La page ne doit pas être vide
cy.get('body').should('not.be.empty');
cy.get('body').invoke('text').should('have.length.greaterThan', 50);

cy.visit('/cette-page-nexiste-vraiment-pas-42', {
  failOnStatusCode: false
});
// Un lien vers l'accueil ou un bouton de retour doit exister
cy.get('a[href="/"], a[href*="cartes.gouv.fr"]', {
  timeout: 10000
}).should('have.length.at.least', 1);

cy.visit('/cette-page-nexiste-vraiment-pas-42', {
  failOnStatusCode: false
});
// Le header DSFR doit être visible
cy.get('header, .fr-header', {
  timeout: 10000
}).should('exist');
// Le footer DSFR doit être visible
cy.get('footer, .fr-footer', {
  timeout: 10000
}).should('exist');

cy.visit('/rechercher-une-donnee/dataset/DATASET_QUI_NEXISTE_PAS_999', {
  failOnStatusCode: false
});
// La page ne doit pas crasher (pas d'écran blanc)
cy.get('body').should('not.be.empty');

const pages = ['/', '/rechercher-une-donnee', '/decouvrir/', '/mentions-legales', '/accessibilite'];
pages.forEach(page => {
  cy.request({
    url: page,
    timeout: 15000
  }).then(response => {
    expect(response.status, `${page} doit répondre 200`).to.eq(200);
  });
});
